@code {
    private RecipeFormModel _model = new();
    private List<string> _categories = new();
    private bool _submitted;
    private string _title = "";
    private int _submittedId;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        var category = _model.Category == "__new__" && !string.IsNullOrWhiteSpace(_model.NewCategory)
            ? _model.NewCategory.Trim()
            : _model.Category;

        var ingredients = _model.IngredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = _model.StepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        _title = _model.Title;
        var recipe = RecipeService.AddRecipe(_model.Title, category, _model.Description, ingredients, steps);
        _submittedId = recipe.Id;
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        public string NewCategory { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add a description.")]
        public string Description { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one ingredient.")]
        public string IngredientsText { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one step.")]
        public string StepsText { get; set; } = "";
    }
}
