@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="@star star(s)">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    @if (_hasRated)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private bool _hasRated;

    private async Task Rate(int stars)
    {
        if (_hasRated) return;
        _selectedRating = stars;
        _hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
        await OnRated.InvokeAsync(stars);
    }
}

.star-rating {
    font-size: 1.5rem;
    display: inline-flex;
    align-items: center;
    gap: 0.1rem;
}

.star {
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star:hover {
    color: #f0ad4e;
}

.star.filled {
    color: #f0ad4e;
}

@page "/category/{CategoryName}"
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

@if (_recipes.Count == 0)
{
    <h1>No recipes found</h1>
    <p>No recipes found in the "@CategoryName" category.</p>
    <a href="/" class="btn btn-secondary">Back to Home</a>
}
else
{
    <h1>@CategoryName Recipes</h1>
    <p class="lead">@_recipes.Count recipe(s) in this category.</p>

    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body d-flex flex-column">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="mt-auto d-flex justify-content-between align-items-center">
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                            @if (recipe.TotalRatings > 0)
                            {
                                <span class="text-warning">★ @recipe.AverageRating.ToString("F1") (@recipe.TotalRatings)</span>
                            }
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>

    <a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private List<Recipe> _recipes = new();

    protected override void OnInitialized()
    {
        CategoryName = Uri.UnescapeDataString(CategoryName);
        _recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (_recipe is null)
{
    <h1>Recipe not found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-secondary">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@Uri.EscapeDataString(_recipe.Category)">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead">@_recipe.Description</p>

    @if (_recipe.TotalRatings > 0)
    {
        <p class="text-warning fs-5">★ @_recipe.AverageRating.ToString("F1") — @_recipe.TotalRatings rating(s)</p>
    }

    <h3 class="mt-4">Ingredients</h3>
    <ul class="list-group list-group-flush mb-4">
        @foreach (var ingredient in _recipe.Ingredients)
        {
            <li class="list-group-item">@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol class="list-group list-group-numbered mb-4">
        @foreach (var step in _recipe.Steps)
        {
            <li class="list-group-item">@step</li>
        }
    </ol>

    <h4>Rate this recipe</h4>
    <StarRating RecipeId="_recipe.Id" />

    <div class="mt-4">
        <a href="category/@Uri.EscapeDataString(_recipe.Category)" class="btn btn-secondary">← Back to @_recipe.Category</a>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_title</strong>" has been added.</p>
        <a href="recipe/@_submittedId" class="btn btn-primary">View Your Recipe</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g. Grandmother's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in _categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="__new__">+ New category...</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        @if (_model.Category == "__new__")
        {
            <div class="mb-3">
                <label for="newCategory" class="form-label">New Category Name</label>
                <InputText id="newCategory" class="form-control" @bind-Value="_model.NewCategory" placeholder="e.g. French" />
            </div>
        }

        <div class="mb-3">
            <label for="description" class="form-label">Description</label>
            <InputTextArea id="description" class="form-control" @bind-Value="_model.Description" rows="2" placeholder="A brief description of your recipe" />
            <ValidationMessage For="() => _model.Description" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" @bind-Value="_model.IngredientsText" rows="5" placeholder="1 cup flour&#10;2 eggs&#10;..." />
            <ValidationMessage For="() => _model.IngredientsText" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" @bind-Value="_model.StepsText" rows="5" placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;..." />
            <ValidationMessage For="() => _model.StepsText" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private List<string> _categories = new();
    private bool _submitted;
    private string _title = "";
    private int _submittedId;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        var category = _model.Category == "__new__" && !string.IsNullOrWhiteSpace(_model.NewCategory)
            ? _model.NewCategory.Trim()
            : _model.Category;

        var ingredients = _model.IngredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = _model.StepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        _title = _model.Title;
        var recipe = RecipeService.AddRecipe(_model.Title, category, _model.Description, ingredients, steps);
        _submittedId = recipe.Id;
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        public string NewCategory { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add a description.")]
        public string Description { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one ingredient.")]
        public string IngredientsText { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please add at least one step.")]
        public string StepsText { get; set; } = "";
    }
}

